import{_ as l,C as i,o as h,c as p,a3 as s,E as r,w as a,a as t,j as o}from"./chunks/framework.B02wg2PO.js";const k=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"introduction/overview.md","filePath":"introduction/overview.md"}'),u={name:"introduction/overview.md"};function m(g,e,f,v,y,b){const n=i("Card"),d=i("CardGrid"),c=i("Callout");return h(),p("div",null,[e[4]||(e[4]=s('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p>Saidi is a self-hosted AI orchestrator you talk to like a team leader. You give it a brief; it turns that brief into a plan, hands each task to an agent that is scoped to the right repo or the right specialty, checks the result against criteria written <em>before</em> the work started, and reports back with a branch you can review.</p><p>It is not a chat window with a code interpreter bolted on. The unit of work is a <strong>Run</strong> — a durable, resumable thread that survives a server restart, keeps one shared context across every agent that participates, and accumulates its commits on one branch instead of cutting a fresh one every time.</p><h2 id="the-cast" tabindex="-1">The cast <a class="header-anchor" href="#the-cast" aria-label="Permalink to &quot;The cast&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Actor</th><th>What it is</th></tr></thead><tbody><tr><td><strong>You</strong> (the operator)</td><td>The only human in the loop. You brief, approve, and decide.</td></tr><tr><td><strong>PRIME</strong></td><td>The orchestrating agent. It plans, delegates, relays questions, and summarises. You only ever talk to PRIME.</td></tr><tr><td><strong>Project agents</strong></td><td>Repo-scoped agents. One per registered project, working in that repo&#39;s checkout, on that repo&#39;s branch.</td></tr><tr><td><strong>Custom agents</strong></td><td>Non-repo specialists (Finance, Research, Ops…) grouped into <strong>departments</strong>, each with an optional <strong>lead</strong> that routes work to its team.</td></tr></tbody></table><h2 id="the-loop" tabindex="-1">The loop <a class="header-anchor" href="#the-loop" aria-label="Permalink to &quot;The loop&quot;">​</a></h2><ol><li><strong>Brief</strong> — you describe the objective in chat, or start a Run directly.</li><li><strong>Plan</strong> — PRIME freezes a checklist. Every task carries acceptance criteria that a verifier could actually rule on (&quot;<code>npm test</code> passes&quot;, &quot;dist/report.pdf exists&quot;), not quality adjectives.</li><li><strong>Delegate</strong> — PRIME calls <code>delegate_to_project</code> or <code>run_agent</code>. In <em>guided</em> mode the engine itself owns the dispatch loop: it picks ready tasks, batches independent ones, and advances only on a passed verdict.</li><li><strong>Verify</strong> — mechanical checks run first (a shell command judged by its exit code), then an independent model verifier if needed. Evidence is collected by the engine off git — the branch, the base, the commits, the files changed.</li><li><strong>Report</strong> — PRIME summarises. The Run holds the whole thread, the per-call usage ledger, and an append-only verification log that no plan amendment can erase.</li></ol><h2 id="what-makes-it-different" tabindex="-1">What makes it different <a class="header-anchor" href="#what-makes-it-different" aria-label="Permalink to &quot;What makes it different&quot;">​</a></h2>',8)),r(d,{cols:3},{default:a(()=>[r(n,{title:"Verified, not asserted",icon:"verify",href:"/concepts/verification",cta:"Verification"},{default:a(()=>[...e[0]||(e[0]=[t(" A task's ",-1),o("code",null,"done",-1),t(" is a verdict from something other than the agent that did the work. Failing checks are trusted from any source; passing checks are only trusted from a source the Run did not author — because the plan author writes both the criteria and the checks, and naming a criterion is not proving it. ",-1)])]),_:1}),r(n,{title:"Sovereignty by default",icon:"shield",href:"/operations/deployment",cta:"Self-hosting"},{default:a(()=>[...e[1]||(e[1]=[t(" It runs on your machine or your VPS, against your private knowledge, with memory in plain markdown you can read. Config lives in your repos; memory lives in Saidi and is never committed to a client repo. ",-1)])]),_:1}),r(n,{title:"Approval is a real gate",icon:"plan",href:"/reference/project-policy",cta:"Project policy"},{default:a(()=>[...e[2]||(e[2]=[t(" A project's policy decides whether writes need your explicit confirmation, whether work goes on a new ",-1),o("code",null,"saidi/*",-1),t(" branch or the current one, and what command proves it worked. ",-1)])]),_:1})]),_:1}),r(c,{type:"warning",title:"Verification is only as good as the criterion"},{default:a(()=>[...e[3]||(e[3]=[o("p",null,[t("A criterion like "),o("em",null,'"the code is clean"'),t(" cannot be checked by anything. A criterion like "),o("em",null,[t('"'),o("code",null,"npm test"),t(' exits 0"')]),t(" can. The quality of a Run is decided when the plan is written, not when the agent starts typing — see "),o("a",{href:"/docs/concepts/plans-and-tasks"},"Plans & Tasks"),t(".")],-1)])]),_:1}),e[5]||(e[5]=s('<h2 id="where-the-code-lives" tabindex="-1">Where the code lives <a class="header-anchor" href="#where-the-code-lives" aria-label="Permalink to &quot;Where the code lives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>Source</th></tr></thead><tbody><tr><td>Runs, plans, verification</td><td><code>src/orchestrator/runs/</code></td></tr><tr><td>Delegation toolbelt</td><td><code>src/orchestrator/delegate.ts</code></td></tr><tr><td>Agents &amp; departments</td><td><code>src/agents/catalog.ts</code></td></tr><tr><td>Memory</td><td><code>src/memory/</code></td></tr><tr><td>Reflexes &amp; events</td><td><code>src/orchestrator/reflexes/</code>, <code>src/orchestrator/events/</code></td></tr><tr><td>Web UI</td><td><code>client/src/</code></td></tr></tbody></table><p>Next: <a href="./why-saidi">Why Saidi</a> — the problem it exists to solve.</p>',3))])}const _=l(u,[["render",m]]);export{k as __pageData,_ as default};
